"""Editorial pages for the two approved public cases."""

PROJECTS = {
    "fashion": {
        "client": "Модный бренд · NDA", "service": "GEO и SEO",
        "title": "Как модный бренд получил более 10 000 переходов из ИИ?",
        "heading": "10 000+ переходов из нейросетей",
        "lead": "Покупатели находили изделия марки, даже когда спрашивали об обуви без названия бренда. Рассказываем, как за полгода изменились ответы нейросетей и зачем проекту понадобились и журнал, и каталог.",
    },
    "winline": {
        "client": "WINLINE", "service": "GEO-аудит",
        "title": "Как мы провели GEO-аудит WINLINE на 15 000 замеров за 10 дней?",
        "heading": "GEO-аудит WINLINE за 10 дней",
        "lead": "На вопрос об условиях WINLINE нейросеть могла назвать бренд, а за подробностями отправить к посреднику. Мы разобрали 15 000 замеров и показали команде, какие официальные страницы стоит обновить.",
    },
}


def identity(key, asset):
    if key == "winline":
        return f'<img class="case-logo" src="{{PRE}}{asset("cases/winline.svg")}" alt="WINLINE" width="483" height="116">'
    return '<span class="nda-stamp">NDA</span>'


def case_index(asset):
    cards = []
    briefs = {
        'fashion': ('Международный модный бренд', '10 000+ переходов из нейросетей', 'GEO и SEO · 6 месяцев',
                    'Журнал и каталог стали получать переходы по вопросам об изделиях, даже когда покупатель ещё не знал названия марки.'),
        'winline': ('WINLINE', 'Аудит пяти нейросетей за 10 дней', 'Исследование видимости',
                    'Мы проследили, куда нейросети отправляют клиентов за официальными условиями. По результатам связали 124 темы с конкретными страницами сайта.'),
    }
    for key, (client, heading, service, intro) in briefs.items():
        cards.append(f'''<article class="portfolio-entry portfolio-{key}"><a href="{key}/">
          {case_cover(key, asset)}<div class="portfolio-copy"><p class="portfolio-meta">{client}<span>{service}</span></p>
          <h2>{heading}</h2><p>{intro}</p><strong>Читать кейс <span aria-hidden="true">↗</span></strong></div></a></article>''')
    return '''<section class="portfolio-index" id="case-directory"><div class="wrap">
      <header><h1>Кейсы GEO</h1><p class="short-answer">В одном проекте помогли покупателям находить модный бренд. В другом выяснили, куда ответы нейросетей ведут клиентов WINLINE.</p></header>
      <div class="portfolio-list">'''+''.join(cards)+'</div></div></section>'


def fashion_story():
    return """<div class="story-flow">
    <section id="the-brand" class="story-chapter"><h2>Покупатели знали марку по имени</h2>
    <p>У марки люксовой обуви, одежды и аксессуаров было два сайта. Один рассказывал о бренде, на втором можно было выбрать изделие. Знакомый с маркой покупатель мог найти оба сайта по названию. В ответах на вопросы о покупке она появлялась редко. Иногда нейросеть ошибалась даже в том, чем занимается её основатель.</p>
    <p>Задача была двойной. Тем, кто уже слышал о марке, нужны точные сведения о ней. Тем, кто только выбирает обувь или аксессуар, нужен путь к конкретному изделию.</p></section>
    <section id="journal" class="story-chapter"><h2>Журнал и каталог на трёх языках</h2>
    <p>Мы собрали 300 поисковых запросов и объединили их в 100 тем. На сайте бренда выходили журнальные материалы, а из них читатель мог перейти к изделиям в каталоге. Для этого мы пересмотрели структуру двух сайтов, поправили микроразметку, связали языковые версии и расставили внутренние ссылки.</p>
    <p>Команда подготовила больше 50 статей и переводов. Если считать каждую опубликованную языковую версию отдельно, в журнале их набралось 132. Первые три месяца работали без покупки ссылок. Платные размещения добавили позже.</p></section>
    <section id="timeline" class="story-interlude"><div class="story-interlude-head"><h2>Как менялись ответы за полгода</h2>
    <p>В первый месяц нейросети стали точнее описывать марку. К пятому месяцу ChatGPT и Perplexity назвали её в ответах на вопросы о покупке.</p></div>
    <ol class="case-timeline">
    <li><span>1-й месяц</span><strong>Верное описание</strong><p>В ответах о бренде ИИ стал называть его реальную деятельность.</p></li>
    <li><span>3-й месяц</span><strong>Товары в поиске</strong><p>Карточки изделий появились в Google и в поиске с ИИ.</p></li>
    <li><span>5-й месяц</span><strong>Первая рекомендация</strong><p>В отдельных ответах о ручной работе в Дубае ChatGPT и Perplexity назвали марку первой.</p></li>
    <li><span>6-й месяц</span><strong>10 000+ переходов</strong><p>Столько переходов из нейросетей накопилось за полгода на двух сайтах.</p></li></ol></section>
    <section id="from-ai" class="story-chapter"><h2>Что привело людей в каталог</h2>
    <p>Около 10 000 переходов из общего числа пришлись на небрендовый спрос. Люди начинали с вопроса о самой вещи. За последние три месяца проекта Ahrefs зафиксировал 190 небрендовых промптов.</p>
    <p>Один из таких сценариев касался покупки изделия ручной работы в Дубае. В сохранённых ответах двух нейросетей бренд стоял на первом месте. Точную формулировку запроса и название клиента мы сохранили в тайне по условиям NDA.</p>
    <p>Для октябрьского контроля мы взяли 100 промптов. По каждому проверили упоминание марки в ChatGPT и Perplexity и присутствие её сайта в источниках. Один вопрос мог дать оба результата. В источниках встретились 20 разных URL двух сайтов.</p>
    <figure class="case-measures"><figcaption>Как читать цифры проекта</figcaption><dl>
    <div><dt>10&nbsp;000+</dt><dd>переходов из нейросетей на два сайта за полгода</dd></div>
    <div><dt>190</dt><dd>небрендовых промптов за последние три месяца по данным Ahrefs</dd></div>
    <div><dt>20</dt><dd>разных страниц двух сайтов в источниках октябрьской проверки</dd></div></dl></figure></section>
    <section id="search" class="story-chapter"><h2>Что происходило в обычном поиске</h2>
    <p>Google Search Console за доступную часть полугодия показала 135 159 кликов и 1 368 682 показа по двум сайтам. В статистике было больше 50 небрендовых поисковых запросов. Это совокупный результат Google за период. Переходы из нейросетей мы считали отдельно.</p>
    <p>За время проекта присутствие бренда расширилось ещё на четыре рынка. Их названия закрыты по NDA. У брендового домена изменился и рейтинг Ahrefs (DR): в августе он составлял 1,8, в ноябре достиг 3,6. DR отражает оценку домена самим Ahrefs.</p>
    <p>В конце полугодия у марки было три пути к каталогу. Читатель мог открыть статью в журнале, найти карточку изделия в Google или прийти по рекомендации нейросети.</p></section></div>"""


def winline_story():
    return """<div class="story-flow">
    <section id="audience" class="story-chapter"><h2>О чём спрашивали клиенты WINLINE</h2>
    <p>Болельщик может спросить о карьере игрока, а через минуту — о правилах расчёта ставки. В первом ответе ему пригодится спортивная справка, во втором ему нужны действующие условия компании. Чтобы охватить оба сценария, мы взяли согласованный с WINLINE список вопросов и исторические данные Wordstat по запросам заказчика.</p>
    <p>Вопросы распределились по четырём группам. В спортивную справку вошли персоны и клубы. В объяснения ставок попали термины, расчёты и стратегии. Отдельно собрали рейтинги и подборки, где клиент выбирает между компаниями. Последняя группа касалась самого WINLINE: как пользоваться продуктом, зарегистрироваться и разобраться в акциях.</p></section>
    <section id="panel" class="story-interlude study-board"><div class="story-interlude-head"><h2>Как получились 15 000 замеров</h2>
    <p>Каждая модель получила одни и те же 300 вопросов по десять раз. Так мы могли вернуться к одному вопросу и посмотреть, повторяется ли наблюдение.</p></div>
    <figure class="study-sample"><figcaption>300 вопросов в каждом прогоне</figcaption><ul>""" + ''.join(
        f'<li><span>{name}</span><i aria-hidden="true"></i><b>10 прогонов</b></li>'
        for name in ('Алиса', 'ChatGPT', 'Perplexity', 'Gemini', 'Claude')
    ) + """</ul><p>5 моделей × 10 прогонов × 300 вопросов = <strong>15 000 замеров</strong></p></figure></section>
    <section id="sources" class="story-chapter"><h2>Бренд называли, а ссылку давали на посредника</h2>
    <p>Имя WINLINE могло встретиться в тексте, а ссылка вести на публикацию посредника. Если считать только упоминания, такой ответ выглядит как присутствие бренда. Для команды было важно другое: может ли человек открыть официальные условия там, где возник вопрос.</p>
    <dl class="case-signals"><div><dt>Название</dt><dd>Кого читатель видит в тексте и какими словами нейросеть объясняет выбор.</dd></div>
    <div><dt>Источник</dt><dd>Чей домен указан среди материалов, на которые опирается ответ.</dd></div>
    <div><dt>Прямая ссылка</dt><dd>Какую страницу читатель может открыть прямо из текста.</dd></div></dl>
    <p>Так же разобрали конкурентов. Сравнили, как модели описывают их предложения, какие домены берут за основу и на чьи страницы дают прямую ссылку. Условия регистрации и акций выделили для отдельной сверки с официальными материалами WINLINE.</p></section>
    <section id="evidence" class="story-chapter"><h2>От строки отчёта к исходному ответу</h2>
    <p>Для каждого замера сохранили исходный запрос, дату, модель и её версию, номер прогона, полный текст ответа и ссылки на источники. Если модель отказалась отвечать, вернула ошибку или оборвала ответ, это тоже попадало в запись.</p>
    <p>Такая запись пригодилась при подготовке рекомендаций. Редактор может открыть ответ о регистрации, прочитать конкретную фразу и сверить её с условиями на сайте. Разработчик видит, какой адрес вернула модель и куда он должен вести.</p></section>
    <section id="delivery" class="story-interlude delivery-spread"><div class="story-interlude-head"><h2>Карта из 124 тем</h2>
    <p>Мы связали 124 темы с 300 вопросами и 119 адресами WINLINE. Для каждой темы указали страницу, с которой стоит работать.</p></div>
    <div class="delivery-pair"><div><strong>12 листов</strong><span>Рабочая книга с аналитикой, исходными ответами, ссылками и рекомендациями по страницам.</span></div>
    <div><strong>26 слайдов</strong><span>Презентация аудита с выводами для редакции, SEO и разработки.</span></div></div></section>
    <section id="priorities" class="story-chapter"><h2>Что могли изменить редакторы и разработчики</h2>
    <p>Редакции передали тему, адрес страницы и вопрос читателя. В задачах расписали, что уточнить в тексте, какой формат ответа подойдёт и где нужны пример, пояснение или источник. Основанием послужили ответы ИИ и материалы конкурентов.</p>
    <p>Разработчикам передали адреса страниц для проверки. Для каждой указали, что посмотреть в коде, как открывается URL и доступны ли текст и ссылки. В результате у команды была связь между вопросом покупателя, фразой нейросети и страницей, которую предстояло изменить. По той же теме можно провести следующий замер после публикации.</p></section></div>"""


def case_cover(key, asset):
    if key == "fashion":
        return f'''<figure class="fashion-cover"><img src="{{PRE}}{asset('shoe-editorial.webp')}"
        width="1440" height="960" alt="Чёрный кожаный лофер на светлом подиуме">
        <figcaption>Иллюстрация к кейсу под NDA</figcaption></figure>'''
    return f'''<figure class="field-cover"><img src="{{PRE}}{asset('cases/stadium.webp')}"
        width="1152" height="1438" alt="Пустые трибуны под мачтой стадионного освещения">
        <figcaption><b>15 000</b> замеров</figcaption></figure>'''


def case_article(key, asset):
    project = PROJECTS[key]
    art = case_cover(key, asset)
    if key == "fashion":
        story = fashion_story()
        index = '<a href="#the-brand">Исходная задача</a><a href="#journal">Журнал и каталог</a><a href="#timeline">Ход проекта</a><a href="#from-ai">Переходы из ИИ</a><a href="#search">Поиск Google</a>'
        subhead = "Международный модный бренд · Дубай"
    else:
        story = winline_story()
        index = '<a href="#audience">Вопросы аудитории</a><a href="#panel">Выборка</a><a href="#sources">Упоминания и ссылки</a><a href="#evidence">Проверка ответов</a><a href="#delivery">Что передали</a><a href="#priorities">Задачи для команды</a>'
        subhead = "Исследование видимости бренда"
    metrics = (
        (('10 000+', 'переходов из нейросетей'), ('6 месяцев', 'срок продвижения'), ('3 языка', 'версии публикаций'))
        if key == "fashion" else
        (('15 000', 'замеров за десять дней'), ('124 темы', 'в карте спроса'), ('119 URL', 'страниц сайта в отчёте'))
    )
    facts = ''.join(f'<div><dt>{value}</dt><dd>{label}</dd></div>' for value, label in metrics)
    return f'''<article class="reportage story-{key}"><header class="story-top"><div class="story-cover wrap"><div class="story-title">
      <div class="case-identity">{identity(key, asset)}<span>{subhead}</span></div>
      <h1>{project['heading']}</h1><p class="short-answer">{project['lead']}</p></div>{art}
      <dl class="story-facts">{facts}</dl></div></header>
      <div class="case-spread wrap">{story}<nav class="case-contents" aria-label="Главы кейса"><strong>В этом кейсе</strong>{index}</nav></div></article>'''
